#include <stdio.h>

/* teste do desafio soma-digitada — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Quem DIGITA e o teste: fopen/fprintf escrevem num arquivo o que o aluno
   digitaria, o freopen troca o stdin por esse arquivo, e a captura do
   stdout acontece dentro do proprio cenario (freopen + fflush, sem
   fclose no stdout). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void somaDigitada(void);

SM_TEST(soma_de_3_e_4_na_mesma_linha) {
    FILE *digitado = fopen("sm_entrada_1.tmp", "w");
    fprintf(digitado, "3 4\n");
    fclose(digitado);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    somaDigitada();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a soma de 3 e 4", linha, "7\n",
              "os dois %d leem 3 e 4 na mesma chamada, e a soma impressa e 7");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na linha da soma: nenhuma linha extra e aceita");
    fclose(f);
}

SM_TEST(enter_no_lugar_do_espaco) {
    FILE *digitado = fopen("sm_entrada_2.tmp", "w");
    fprintf(digitado, "10\n7\n");
    fclose(digitado);
    freopen("sm_entrada_2.tmp", "r", stdin);

    freopen("sm_saida_2.tmp", "w", stdout);
    somaDigitada();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a soma de 10 e 7 digitados em duas linhas", linha, "17\n",
              "o Enter separa os dois %d igual ao espaco: 10 mais 7 da 17");
    fclose(f);
}

